import React, { useEffect, useState, useRef, useCallback } from 'react';
import { useOutletContext } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

/* ════════════════════════════════════════════════
   HELPERS
════════════════════════════════════════════════ */
function StatutBadge({ statut }) {
  const cfg = {
    en_attente: { bg: 'rgba(245,158,11,0.12)',  color: '#f59e0b', dot: '#f59e0b', label: 'En attente'  },
    confirmé:   { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', dot: '#43e97b', label: 'Confirmé'    },
    refusé:     { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', dot: '#ff6584', label: 'Refusé'      },
    annulé:     { bg: 'rgba(153,153,187,0.12)', color: '#9999bb', dot: '#9999bb', label: 'Annulé'      },
    terminé:    { bg: 'rgba(56,189,248,0.12)',  color: '#38bdf8', dot: '#38bdf8', label: 'Terminé'     },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', dot: 'var(--text2)', label: statut };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 5, fontSize: '.72rem', fontWeight: 700, padding: '4px 11px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      <span style={{ width: 6, height: 6, borderRadius: '50%', background: cfg.dot, flexShrink: 0 }} />
      {cfg.label}
    </span>
  );
}

function ModeBadge({ mode }) {
  if (!mode) return null;
  const cfg = mode === 'en_ligne'
    ? { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.1)' }
    : { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.1)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.7rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.icon} {cfg.label}
    </span>
  );
}

function formatDate(str) {
  if (!str) return '—';
  return new Date(str + 'T00:00:00').toLocaleDateString('fr-FR', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
  });
}

function formatTime(str) {
  if (!str) return '';
  const d = new Date(str);
  const diff = Math.floor((new Date() - d) / 1000);
  if (diff < 60)    return 'À l\'instant';
  if (diff < 3600)  return `${Math.floor(diff / 60)} min`;
  if (diff < 86400) return `${Math.floor(diff / 3600)}h`;
  return d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
}

function Avatar({ nom, size = 36 }) {
  const initials = (nom || 'P').split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);
  return (
    <div style={{ width: size, height: size, borderRadius: '50%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: size * 0.35, fontWeight: 700, color: '#fff', flexShrink: 0 }}>
      {initials}
    </div>
  );
}

/* ════════════════════════════════════════════════
   FENÊTRE DE MESSAGERIE
════════════════════════════════════════════════ */
function ChatWindow({ reservation, currentUser, onClose, onNewMessage }) {
  const [messages, setMessages]   = useState([]);
  const [input, setInput]         = useState('');
  const [sending, setSending]     = useState(false);
  const [uploading, setUploading] = useState(false);
  const bottomRef  = useRef(null);
  const fileRef    = useRef(null);
  const pollRef    = useRef(null);

  const profNom = reservation.prof_nom || 'Professeur';

  const loadMessages = useCallback(async () => {
    try {
      const res = await api.get(`/api/messages/reservation/${reservation.id}`);
      setMessages(res.data);
    } catch { /* silencieux */ }
  }, [reservation.id]);

  useEffect(() => {
    loadMessages();
    // Polling toutes les 3s
    pollRef.current = setInterval(loadMessages, 3000);
    return () => clearInterval(pollRef.current);
  }, [loadMessages]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendText = async () => {
    if (!input.trim() || sending) return;
    setSending(true);
    try {
      const res = await api.post(`/api/messages/reservation/${reservation.id}`, { contenu: input.trim() });
      setMessages(prev => [...prev, res.data]);
      setInput('');
      onNewMessage?.();
    } catch (e) {
      alert('Erreur envoi : ' + (e.response?.data?.detail || e.message));
    } finally {
      setSending(false);
    }
  };

  const sendFile = async (file) => {
    if (!file) return;
    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post(
        `/api/messages/reservation/${reservation.id}/fichier`,
        fd,
        { headers: { 'Content-Type': 'multipart/form-data' } }
      );
      setMessages(prev => [...prev, res.data]);
      onNewMessage?.();
    } catch (e) {
      alert('Erreur upload : ' + (e.response?.data?.detail || e.message));
    } finally {
      setUploading(false);
    }
  };

  const handleKey = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendText(); }
  };

  const renderFile = (msg) => {
    const url = `http://localhost:8001${msg.fichier_url}`;
    if (msg.fichier_type === 'image') {
      return (
        <a href={url} target="_blank" rel="noreferrer">
          <img src={url} alt={msg.fichier_nom} style={{ maxWidth: 220, maxHeight: 180, borderRadius: 10, display: 'block', objectFit: 'cover', cursor: 'pointer' }} />
        </a>
      );
    }
    return (
      <a href={url} target="_blank" rel="noreferrer" style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'rgba(255,255,255,0.1)', borderRadius: 10, textDecoration: 'none', color: 'inherit' }}>
        <span style={{ fontSize: '1.4rem' }}>{msg.fichier_type === 'pdf' ? '📄' : '📎'}</span>
        <div>
          <div style={{ fontWeight: 600, fontSize: '.82rem' }}>{msg.fichier_nom}</div>
          <div style={{ fontSize: '.72rem', opacity: .7 }}>Cliquer pour ouvrir</div>
        </div>
      </a>
    );
  };

  const isMine = (msg) => msg.expediteur_id === currentUser.id;

  return (
    <div style={{
      position: 'fixed', bottom: 24, right: 24,
      width: 380, height: 560,
      background: 'var(--surface)', border: '1px solid var(--border)',
      borderRadius: 20, display: 'flex', flexDirection: 'column',
      boxShadow: '0 24px 80px rgba(0,0,0,0.5)',
      zIndex: 1000, animation: 'chatIn .3s cubic-bezier(.34,1.56,.64,1)',
      overflow: 'hidden',
    }}>
      <style>{`
        @keyframes chatIn {
          from { opacity:0; transform: scale(.9) translateY(20px); }
          to   { opacity:1; transform: scale(1) translateY(0); }
        }
      `}</style>

      {/* Header chat */}
      <div style={{ padding: '14px 16px', background: 'linear-gradient(135deg,rgba(108,99,255,.25),rgba(255,101,132,.15))', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: 12 }}>
        <Avatar nom={profNom} size={40} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '.92rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{profNom}</div>
          <div style={{ fontSize: '.72rem', color: 'var(--text2)' }}>
            📅 {reservation.date_cours ? formatDate(reservation.date_cours) : '—'}
          </div>
        </div>
        <button onClick={onClose} style={{ width: 30, height: 30, borderRadius: 8, background: 'rgba(255,255,255,0.1)', border: 'none', cursor: 'pointer', color: 'var(--text)', fontSize: '.9rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>✕</button>
      </div>

      {/* Messages */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '14px 14px 4px', display: 'flex', flexDirection: 'column', gap: 8 }}>
        {messages.length === 0 && (
          <div style={{ textAlign: 'center', padding: '30px 16px', color: 'var(--text2)' }}>
            <div style={{ fontSize: '2rem', marginBottom: 8 }}>💬</div>
            <div style={{ fontSize: '.82rem' }}>Démarrez la conversation avec votre professeur.</div>
          </div>
        )}
        {messages.map(msg => {
          const mine = isMine(msg);
          return (
            <div key={msg.id} style={{ display: 'flex', flexDirection: mine ? 'row-reverse' : 'row', alignItems: 'flex-end', gap: 7 }}>
              {!mine && <Avatar nom={msg.expediteur_nom} size={26} />}
              <div style={{ maxWidth: '72%' }}>
                <div style={{
                  padding: msg.fichier_url ? '6px' : '9px 13px',
                  borderRadius: mine ? '16px 16px 4px 16px' : '16px 16px 16px 4px',
                  background: mine ? 'linear-gradient(135deg,#6c63ff,#8b5cf6)' : 'var(--surface2)',
                  color: mine ? '#fff' : 'var(--text)',
                  fontSize: '.85rem', lineHeight: 1.5,
                  border: mine ? 'none' : '1px solid var(--border)',
                }}>
                  {msg.contenu && <span>{msg.contenu}</span>}
                  {msg.fichier_url && renderFile(msg)}
                </div>
                <div style={{ fontSize: '.65rem', color: 'var(--text2)', marginTop: 3, textAlign: mine ? 'right' : 'left' }}>
                  {formatTime(msg.created_at)}
                  {mine && <span style={{ marginLeft: 4 }}>{msg.lu ? ' ✓✓' : ' ✓'}</span>}
                </div>
              </div>
            </div>
          );
        })}
        <div ref={bottomRef} />
      </div>

      {/* Zone de saisie */}
      <div style={{ padding: '10px 12px', borderTop: '1px solid var(--border)', display: 'flex', alignItems: 'flex-end', gap: 8, background: 'var(--surface)' }}>
        {/* Bouton fichier */}
        <button
          onClick={() => fileRef.current?.click()}
          disabled={uploading}
          style={{ width: 36, height: 36, borderRadius: 10, background: 'var(--surface2)', border: '1px solid var(--border)', cursor: uploading ? 'not-allowed' : 'pointer', color: 'var(--text2)', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
          title="Envoyer un fichier"
        >
          {uploading ? '⏳' : '📎'}
        </button>
        <input ref={fileRef} type="file" hidden accept="image/*,.pdf,.doc,.docx,.txt" onChange={e => sendFile(e.target.files[0])} />

        {/* Input texte */}
        <textarea
          rows={1}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleKey}
          placeholder="Votre message..."
          style={{ flex: 1, background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 12, padding: '9px 12px', color: 'var(--text)', fontSize: '.85rem', resize: 'none', outline: 'none', fontFamily: 'DM Sans, sans-serif', maxHeight: 80, overflowY: 'auto' }}
        />

        {/* Envoyer */}
        <button
          onClick={sendText}
          disabled={!input.trim() || sending}
          style={{ width: 36, height: 36, borderRadius: 10, border: 'none', cursor: (!input.trim() || sending) ? 'not-allowed' : 'pointer', background: (!input.trim() || sending) ? 'var(--surface2)' : 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, transition: 'all .2s' }}
        >
          {sending ? '⏳' : '➤'}
        </button>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   BLOC GOOGLE MEET — affichage intelligent selon timing
════════════════════════════════════════════════ */
function MeetBlock({ r }) {
  // Toujours visible si confirmé + en ligne, mais avec un état différent selon le timing
  if (r.session_past) {
    // Session passée : lien toujours accessible mais grisé
    return (
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'rgba(153,153,187,0.08)', border: '1px solid rgba(153,153,187,0.2)', borderRadius: 12, marginBottom: 14 }}>
        <span style={{ fontSize: '1rem' }}>🎥</span>
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: '.8rem', fontWeight: 600, color: 'var(--text2)' }}>Session terminée</div>
          <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ fontSize: '.7rem', color: '#9999bb', textDecoration: 'none' }}>
            Accéder au lien Meet →
          </a>
        </div>
      </div>
    );
  }

  if (r.session_active) {
    // Session EN COURS — bouton pulsant vert
    return (
      <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ textDecoration: 'none', display: 'block', marginBottom: 14 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '12px 16px', background: 'linear-gradient(135deg,rgba(67,233,123,0.15),rgba(56,189,248,0.1))', border: '2px solid rgba(67,233,123,0.5)', borderRadius: 14, cursor: 'pointer', animation: 'meetPulse 2s infinite' }}>
          <style>{`@keyframes meetPulse{0%,100%{box-shadow:0 0 0 0 rgba(67,233,123,0.4)}50%{box-shadow:0 0 0 8px rgba(67,233,123,0)}}`}</style>
          <div style={{ width: 36, height: 36, borderRadius: 10, background: 'linear-gradient(135deg,#43e97b,#38f9d7)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}>🎥</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: '.85rem', fontWeight: 800, color: '#43e97b', display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ width: 8, height: 8, borderRadius: '50%', background: '#43e97b', display: 'inline-block', animation: 'blink 1s infinite' }} />
              Session en cours — Rejoindre maintenant
            </div>
            <div style={{ fontSize: '.72rem', color: 'var(--text2)', marginTop: 2 }}>{r.lien_meet}</div>
          </div>
          <span style={{ fontSize: '.9rem', color: '#43e97b', fontWeight: 700 }}>→</span>
        </div>
        <style>{`@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}`}</style>
      </a>
    );
  }

  if (r.session_imminent) {
    // Session dans moins de 30 min — bouton orange/jaune
    return (
      <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ textDecoration: 'none', display: 'block', marginBottom: 14 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '11px 15px', background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.4)', borderRadius: 13, cursor: 'pointer' }}>
          <div style={{ width: 34, height: 34, borderRadius: 9, background: 'rgba(245,158,11,0.2)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', flexShrink: 0 }}>🎥</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: '.83rem', fontWeight: 700, color: '#f59e0b' }}>
              Session dans {r.minutes_until} minute{r.minutes_until > 1 ? 's' : ''} — Se préparer
            </div>
            <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginTop: 2 }}>{r.lien_meet}</div>
          </div>
          <span style={{ fontSize: '.85rem', color: '#f59e0b', fontWeight: 700 }}>→</span>
        </div>
      </a>
    );
  }

  if (r.session_today) {
    // Aujourd'hui mais pas encore imminent — lien bleu standard
    return (
      <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ textDecoration: 'none', display: 'block', marginBottom: 14 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.35)', borderRadius: 12, cursor: 'pointer' }}>
          <div style={{ width: 34, height: 34, borderRadius: 9, background: 'rgba(56,189,248,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', flexShrink: 0 }}>🎥</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: '.83rem', fontWeight: 700, color: '#38bdf8' }}>Cours aujourd'hui — Lien Meet disponible</div>
            <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginTop: 2 }}>{r.lien_meet}</div>
          </div>
          <span style={{ fontSize: '.85rem', color: '#38bdf8', fontWeight: 700 }}>→</span>
        </div>
      </a>
    );
  }

  // Session future — lien visible mais discret avec date de disponibilité
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', background: 'rgba(108,99,255,0.06)', border: '1px solid rgba(108,99,255,0.2)', borderRadius: 12, marginBottom: 14 }}>
      <div style={{ width: 34, height: 34, borderRadius: 9, background: 'rgba(108,99,255,0.12)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', flexShrink: 0 }}>🎥</div>
      <div style={{ flex: 1 }}>
        <div style={{ fontSize: '.8rem', fontWeight: 600, color: '#6c63ff' }}>Lien Meet — Disponible le jour J</div>
        <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginTop: 2 }}>
          📅 Le lien sera actif le {formatDate(r.date_cours)} à {r.heure_debut}
        </div>
      </div>
      <a href={r.lien_meet} target="_blank" rel="noreferrer" style={{ fontSize: '.72rem', color: '#6c63ff', fontWeight: 600, textDecoration: 'none', background: 'rgba(108,99,255,0.1)', padding: '4px 10px', borderRadius: 20 }}>
        Accéder ↗
      </a>
    </div>
  );
}

/* ════════════════════════════════════════════════
   CARTE RÉSERVATION
════════════════════════════════════════════════ */
function ReservationCard({ r, onChat, unreadCount }) {
  const [expanded, setExpanded] = useState(false);
  const isFuture = r.date_cours && new Date(r.date_cours + 'T23:59:59') >= new Date();

  return (
    <div style={{
      background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20,
      overflow: 'hidden', transition: 'all .2s',
    }}>
      {/* Bande colorée selon statut */}
      <div style={{ height: 4, background: r.statut === 'confirmé' ? 'linear-gradient(90deg,#43e97b,#38f9d7)' : r.statut === 'en_attente' ? 'linear-gradient(90deg,#f59e0b,#fbbf24)' : r.statut === 'refusé' ? 'linear-gradient(90deg,#ff6584,#f43f5e)' : 'linear-gradient(90deg,#38bdf8,#818cf8)' }} />

      <div style={{ padding: '20px 22px' }}>
        {/* Header card */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <Avatar nom={r.prof_nom} size={48} />
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', marginBottom: 4 }}>{r.prof_nom || 'Professeur'}</div>
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
                <StatutBadge statut={r.statut} />
                <ModeBadge mode={r.mode_seance} />
                {isFuture && r.statut === 'confirmé' && (
                  <span style={{ fontSize: '.68rem', fontWeight: 700, padding: '2px 8px', borderRadius: 20, background: 'rgba(108,99,255,0.12)', color: '#6c63ff' }}>
                    📅 À venir
                  </span>
                )}
              </div>
            </div>
          </div>

          {/* Bouton chat */}
          {r.statut === 'confirmé' && (
            <button
              onClick={() => onChat(r)}
              style={{ position: 'relative', display: 'flex', alignItems: 'center', gap: 7, padding: '9px 16px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 12, fontWeight: 600, cursor: 'pointer', fontSize: '.82rem', flexShrink: 0, boxShadow: '0 4px 14px rgba(108,99,255,0.3)' }}
            >
              <span style={{ fontSize: '1rem' }}>💬</span>
              Contacter
              {unreadCount > 0 && (
                <span style={{ position: 'absolute', top: -6, right: -6, background: '#ff6584', color: '#fff', fontSize: '.6rem', fontWeight: 800, padding: '1px 5px', borderRadius: 20, minWidth: 16, textAlign: 'center', border: '2px solid var(--card)' }}>
                  {unreadCount}
                </span>
              )}
            </button>
          )}
        </div>

        {/* Infos principales */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 10, marginBottom: 14 }}>
          <InfoBlock icon="📅" label="Date" value={formatDate(r.date_cours)} />
          <InfoBlock icon="🕒" label="Horaire" value={`${String(r.heure_debut || '').slice(0,5)} → ${String(r.heure_fin || '').slice(0,5)}`} />
          {r.tarif_applique && <InfoBlock icon="💰" label="Tarif" value={`${r.tarif_applique} DT/h`} color="#43e97b" />}
        </div>

        {/* Lien Meet — affiché si en ligne + confirmé, avec statut visuel selon le timing */}
        {r.mode_seance === 'en_ligne' && r.lien_meet && r.statut === 'confirmé' && (
          <MeetBlock r={r} />
        )}

        {/* Bouton voir plus */}
        <button
          onClick={() => setExpanded(!expanded)}
          style={{ background: 'none', border: 'none', color: 'var(--text2)', cursor: 'pointer', fontSize: '.78rem', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 4, padding: 0 }}
        >
          {expanded ? '▲ Moins de détails' : '▼ Plus de détails'}
        </button>

        {/* Détails expandables */}
        {expanded && (
          <div style={{ marginTop: 14, padding: '14px', background: 'var(--surface2)', borderRadius: 12, border: '1px solid var(--border)', display: 'flex', flexDirection: 'column', gap: 8 }}>
            {r.prof_email && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.82rem' }}>
                <span style={{ color: 'var(--text2)', width: 80 }}>✉️ Email</span>
                <a href={`mailto:${r.prof_email}`} style={{ color: '#6c63ff', textDecoration: 'none', fontWeight: 600 }}>{r.prof_email}</a>
              </div>
            )}
            {r.prof_telephone && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.82rem' }}>
                <span style={{ color: 'var(--text2)', width: 80 }}>📞 Tél</span>
                <a href={`tel:${r.prof_telephone}`} style={{ color: '#6c63ff', textDecoration: 'none', fontWeight: 600 }}>{r.prof_telephone}</a>
              </div>
            )}
            {r.notes_etudiant && (
              <div style={{ fontSize: '.82rem' }}>
                <span style={{ color: 'var(--text2)' }}>💬 Votre message : </span>
                <span style={{ fontStyle: 'italic' }}>{r.notes_etudiant}</span>
              </div>
            )}
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.78rem', color: 'var(--text2)' }}>
              <span>🕐 Réservation créée le</span>
              <span>{r.created_at ? new Date(r.created_at).toLocaleDateString('fr-FR') : '—'}</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function InfoBlock({ icon, label, value, color }) {
  return (
    <div style={{ background: 'var(--surface2)', padding: '10px 12px', borderRadius: 10, border: '1px solid var(--border)' }}>
      <div style={{ fontSize: '.7rem', color: 'var(--text2)', marginBottom: 4 }}>{icon} {label}</div>
      <div style={{ fontWeight: 700, fontSize: '.82rem', color: color || 'var(--text)' }}>{value}</div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   PAGE PRINCIPALE — MES RÉSERVATIONS
════════════════════════════════════════════════ */
export default function MesReservations() {
  const { user } = useAuth();

  // Reçoit chatResaId depuis Layout quand l'étudiant clique sur une notif de message
  const outletCtx = useOutletContext?.() || {};
  const { chatResaId, setChatResaId } = outletCtx;

  const [reservations, setReservations] = useState([]);
  const [loading, setLoading]           = useState(true);
  const [activeFilter, setActiveFilter] = useState('toutes');
  const [chatResa, setChatResa]         = useState(null);
  const [unreadMap, setUnreadMap]       = useState({});

  useEffect(() => {
    loadReservations();
    loadUnread();
    const interval = setInterval(loadUnread, 10000);
    return () => clearInterval(interval);
  }, []);

  // Quand les réservations sont chargées ET qu'une notif a demandé l'ouverture d'un chat
  useEffect(() => {
    if (chatResaId && reservations.length > 0) {
      const resa = reservations.find(r => r.id === Number(chatResaId));
      if (resa) {
        setChatResa(resa);
        setChatResaId?.(null); // reset pour ne pas rouvrir à chaque render
      }
    }
  }, [chatResaId, reservations]);

  const loadReservations = async () => {
    try {
      const res = await api.get('/api/reservations/mes-reservations');
      setReservations(res.data);
    } catch { /* silencieux */ }
    finally { setLoading(false); }
  };

  const loadUnread = async () => {
    try {
      const res = await api.get('/api/messages/non-lus');
      const map = {};
      (res.data.messages || []).forEach(m => {
        map[m.reservation_id] = (map[m.reservation_id] || 0) + 1;
      });
      setUnreadMap(map);
    } catch { /* silencieux */ }
  };

  const filters = [
    { key: 'toutes',     label: 'Toutes',          color: '#6c63ff' },
    { key: 'en_attente', label: 'En attente',       color: '#f59e0b' },
    { key: 'confirmé',   label: 'Confirmées',       color: '#43e97b' },
    { key: 'a_venir',    label: 'À venir',          color: '#38bdf8' },
    { key: 'passées',    label: 'Passées',          color: '#9999bb' },
    { key: 'refusé',     label: 'Refusées',         color: '#ff6584' },
  ];

  const filtered = reservations.filter(r => {
    if (activeFilter === 'toutes')     return true;
    if (activeFilter === 'a_venir')    return r.statut === 'confirmé' && r.date_cours && new Date(r.date_cours + 'T23:59:59') >= new Date();
    if (activeFilter === 'passées')    return r.date_cours && new Date(r.date_cours + 'T23:59:59') < new Date();
    return r.statut === activeFilter;
  });

  const counts = {
    toutes:     reservations.length,
    en_attente: reservations.filter(r => r.statut === 'en_attente').length,
    confirmé:   reservations.filter(r => r.statut === 'confirmé').length,
    a_venir:    reservations.filter(r => r.statut === 'confirmé' && r.date_cours && new Date(r.date_cours + 'T23:59:59') >= new Date()).length,
    passées:    reservations.filter(r => r.date_cours && new Date(r.date_cours + 'T23:59:59') < new Date()).length,
    refusé:     reservations.filter(r => r.statut === 'refusé').length,
  };

  const totalUnread = Object.values(unreadMap).reduce((a, b) => a + b, 0);

  return (
    <div style={{ padding: 32, maxWidth: 900, margin: '0 auto' }}>

      {/* HEADER */}
      <div style={{ marginBottom: 28 }}>
        <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.6rem', marginBottom: 6 }}>
          📋 Mes Réservations
        </div>
        <div style={{ color: 'var(--text2)', fontSize: '.88rem' }}>
          Historique de vos sessions — passées et à venir
        </div>
      </div>

      {/* STATS */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 14, marginBottom: 28 }}>
        {[
          { icon: '📅', val: counts.toutes,     lbl: 'Total',          color: '#6c63ff', bg: 'rgba(108,99,255,.1)' },
          { icon: '⏳', val: counts.en_attente, lbl: 'En attente',     color: '#f59e0b', bg: 'rgba(245,158,11,.1)' },
          { icon: '✅', val: counts.confirmé,   lbl: 'Confirmées',     color: '#43e97b', bg: 'rgba(67,233,123,.1)' },
          { icon: '💬', val: totalUnread,        lbl: 'Msgs non lus',  color: '#ff6584', bg: 'rgba(255,101,132,.1)' },
        ].map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '14px 18px', display: 'flex', alignItems: 'center', gap: 12 }}>
            <div style={{ width: 40, height: 40, borderRadius: 11, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.1rem', flexShrink: 0 }}>{s.icon}</div>
            <div>
              <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1.4rem', color: s.color, lineHeight: 1 }}>{s.val}</div>
              <div style={{ fontSize: '.72rem', color: 'var(--text2)', marginTop: 2 }}>{s.lbl}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ALERTE messages non lus */}
      {totalUnread > 0 && (
        <div style={{ marginBottom: 20, padding: '12px 18px', background: 'rgba(255,101,132,0.07)', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 14, display: 'flex', alignItems: 'center', gap: 10 }}>
          <span style={{ fontSize: '1.2rem' }}>💬</span>
          <div style={{ flex: 1 }}>
            <span style={{ fontWeight: 700, color: '#ff6584' }}>{totalUnread} message{totalUnread > 1 ? 's' : ''} non lu{totalUnread > 1 ? 's' : ''}</span>
            <span style={{ color: 'var(--text2)', fontSize: '.82rem' }}> de vos professeurs</span>
          </div>
        </div>
      )}

      {/* FILTRES */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 24, flexWrap: 'wrap' }}>
        {filters.map(f => (
          <button
            key={f.key}
            onClick={() => setActiveFilter(f.key)}
            style={{
              padding: '8px 14px', borderRadius: 20, cursor: 'pointer',
              fontWeight: 600, fontSize: '.8rem', transition: 'all .15s',
              border: activeFilter === f.key ? `1px solid ${f.color}` : '1px solid var(--border)',
              background: activeFilter === f.key ? `${f.color}20` : 'var(--surface2)',
              color: activeFilter === f.key ? f.color : 'var(--text2)',
              display: 'flex', alignItems: 'center', gap: 6,
            }}
          >
            {f.label}
            <span style={{ background: activeFilter === f.key ? f.color : 'var(--border)', color: activeFilter === f.key ? '#000' : 'var(--text2)', fontSize: '.62rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20 }}>
              {counts[f.key]}
            </span>
          </button>
        ))}
      </div>

      {/* LISTE */}
      {loading ? (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {[1,2,3].map(i => <SkeletonCard key={i} />)}
        </div>
      ) : filtered.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '60px 20px', background: 'var(--card)', borderRadius: 20, border: '1px solid var(--border)', color: 'var(--text2)' }}>
          <div style={{ fontSize: '3rem', marginBottom: 14 }}>📭</div>
          <div style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: '1.1rem', marginBottom: 6 }}>Aucune réservation</div>
          <div style={{ fontSize: '.85rem' }}>
            {activeFilter === 'toutes' ? 'Vous n\'avez pas encore de réservation.' : 'Aucune réservation dans cette catégorie.'}
          </div>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
          {filtered
            .sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0))
            .map(r => (
              <ReservationCard
                key={r.id}
                r={r}
                onChat={resa => setChatResa(resa)}
                unreadCount={unreadMap[r.id] || 0}
              />
            ))}
        </div>
      )}

      {/* FENÊTRE CHAT */}
      {chatResa && (
        <ChatWindow
          reservation={chatResa}
          currentUser={user}
          onClose={() => { setChatResa(null); loadUnread(); }}
          onNewMessage={loadUnread}
        />
      )}
    </div>
  );
}

function SkeletonCard() {
  return (
    <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 22 }}>
      <div style={{ display: 'flex', gap: 14, marginBottom: 16 }}>
        <div style={{ width: 48, height: 48, borderRadius: '50%', background: 'var(--surface2)', animation: 'pulse 1.5s infinite', flexShrink: 0 }} />
        <div style={{ flex: 1 }}>
          {[['60%','14px'],['40%','10px']].map(([w,h],i) => <div key={i} style={{ height: h, background: 'var(--surface2)', borderRadius: 6, marginBottom: 8, width: w, animation: 'pulse 1.5s infinite' }} />)}
        </div>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 10 }}>
        {[1,2,3].map(i => <div key={i} style={{ height: 52, background: 'var(--surface2)', borderRadius: 10, animation: 'pulse 1.5s infinite' }} />)}
      </div>
      <style>{`@keyframes pulse{0%,100%{opacity:1}50%{opacity:.4}}`}</style>
    </div>
  );
}
